export type MaxRes = 'auto' | 720 | 1080 | 0;

/**
 * Resolve o ajuste de resolução (PERF-26 / spec 002) para px verticais.
 * `0` = sem teto — o plugin nativo (ou o `<video>` do dev) não restringe.
 *
 * Para `'auto'`, usa o **menor lado** do display × densidade: o app é travado em
 * paisagem (D-19), e o menor lado é sempre a extensão vertical, independente de
 * como o `window.screen` reporta a orientação natural do aparelho.
 */
/** Resoluções verticais padrão — o Auto arredonda para cima até uma destas. */
const RUNGS = [720, 1080, 1440, 2160] as const;

export function tetoResolucaoPx(ajuste: MaxRes): number {
  if (ajuste === 0) return 0;
  if (typeof ajuste === 'number') return ajuste;

  const s = typeof window !== 'undefined' ? window.screen : undefined;
  if (!s) return 0;
  const lado = Math.min(s.width || 0, s.height || 0); // extensão vertical em paisagem
  // `screen` pode vir em px CSS ou de dispositivo conforme o WebView; pega o
  // maior dos dois para nunca cortar abaixo do que a tela realmente mostra
  const vert = Math.max(lado, lado * (window.devicePixelRatio || 1));
  if (vert < 600) return 0; // leitura implausível → sem teto
  return RUNGS.find((r) => vert <= r + 1) ?? Math.round(vert);
}

/** Ordem em que a linha de Configurações cicla o ajuste. */
export const ORDEM_MAX_RES: readonly MaxRes[] = ['auto', 720, 1080, 0];
